#ifndef ZOVUTILS_DD_BACKEND_H
#define ZOVUTILS_DD_BACKEND_H
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/types.h>
static inline int zov_dd_num(const char*s,uint64_t*out){char*e;errno=0;unsigned long long n=strtoull(s,&e,10);if(errno||e==s)return 0;uint64_t m=1;if(*e){if(e[1])return 0;if(*e=='k'||*e=='K')m=1024ULL;else if(*e=='M')m=1024ULL*1024;else if(*e=='G')m=1024ULL*1024*1024;else if(*e=='w')m=2;else return 0;}if(n>UINT64_MAX/m)return 0;*out=n*m;return 1;}
static inline int zov_dd_run(int argc,char**argv){const char*ifile=NULL,*ofile=NULL,*statusopt="default";uint64_t bs=512,count=UINT64_MAX,skip=0,seek=0;int have_bs=0,notrunc=0,append=0;for(int i=0;i<argc;i++){const char*a=argv[i];if(!strcmp(a,"--help")){puts("Usage: dd [OPERAND]...\nCopy a file, converting and formatting according to the operands.\n  if=FILE     read from FILE instead of standard input\n  of=FILE     write to FILE instead of standard output\n  bs=N        read and write up to N bytes at a time\n  count=N     copy only N input blocks\n  skip=N      skip N input blocks\n  seek=N      skip N output blocks\n  conv=CONVS  convert the file as specified by the CONVS symbol list\n  status=LEVEL  The LEVEL of information to print to stderr\n      --help      display this help and exit\n      --version   output version information and exit");return 0;}if(!strcmp(a,"--version")){puts("dd (zovutils) 0.10.59");return 0;}const char*eq=strchr(a,'=');if(!eq){fprintf(stderr,"dd: unrecognized operand '%s'\nTry 'dd --help' for more information.\n",a);return 1;}size_t k=(size_t)(eq-a);const char*v=eq+1;uint64_t x;if(k==2&&!strncmp(a,"if",2))ifile=v;else if(k==2&&!strncmp(a,"of",2))ofile=v;else if(k==2&&!strncmp(a,"bs",2)){if(!zov_dd_num(v,&x)||x==0||x>67108864){fprintf(stderr,"dd: invalid number: '%s'\n",v);return 1;}bs=x;have_bs=1;}else if(k==5&&!strncmp(a,"count",5)){if(!zov_dd_num(v,&count)){fprintf(stderr,"dd: invalid number: '%s'\n",v);return 1;}}else if(k==4&&!strncmp(a,"skip",4)){if(!zov_dd_num(v,&skip)){fprintf(stderr,"dd: invalid number: '%s'\n",v);return 1;}}else if(k==4&&!strncmp(a,"seek",4)){if(!zov_dd_num(v,&seek)){fprintf(stderr,"dd: invalid number: '%s'\n",v);return 1;}}else if(k==4&&!strncmp(a,"conv",4)){if(strstr(v,"notrunc"))notrunc=1;else if(strcmp(v,"sync")&&strcmp(v,"noerror")){fprintf(stderr,"dd: invalid conversion: '%s'\n",v);return 1;}}else if(k==6&&!strncmp(a,"status",6))statusopt=v;else if(k==5&&!strncmp(a,"oflag",5)&&strstr(v,"append"))append=1;else{fprintf(stderr,"dd: unrecognized operand '%s'\nTry 'dd --help' for more information.\n",a);return 1;}}
if(!have_bs)bs=512;if(skip>UINT64_MAX/bs||seek>UINT64_MAX/bs){fprintf(stderr,"dd: invalid number\n");return 1;}FILE*in=stdin,*out=stdout;if(ifile){in=fopen(ifile,"rb");if(!in){fprintf(stderr,"dd: failed to open '%s': %s\n",ifile,strerror(errno));return 1;}}if(ofile){out=fopen(ofile,append?"ab":notrunc?"r+b":"wb");if(!out&&notrunc)out=fopen(ofile,"wb");if(!out){fprintf(stderr,"dd: failed to open '%s': %s\n",ofile,strerror(errno));if(in!=stdin)fclose(in);return 1;}}if(skip){if(fseeko(in,(off_t)(skip*bs),SEEK_SET)!=0){unsigned char tmp[4096];uint64_t left=skip*bs;while(left){size_t r=fread(tmp,1,left>sizeof(tmp)?sizeof(tmp):(size_t)left,in);if(!r)break;left-=r;}}}if(seek&&fseeko(out,(off_t)(seek*bs),SEEK_SET)!=0){if(in!=stdin)fclose(in);if(out!=stdout)fclose(out);return 1;}unsigned char*buf=(unsigned char*)malloc((size_t)bs);if(!buf){if(in!=stdin)fclose(in);if(out!=stdout)fclose(out);return 1;}uint64_t records=0,bytes=0;int status=0;while(records<count){size_t n=fread(buf,1,(size_t)bs,in);if(!n)break;if(fwrite(buf,1,n,out)!=n){status=1;break;}bytes+=n;records++;if(n<bs)break;}if(fflush(out)!=0)status=1;if(in!=stdin)fclose(in);if(out!=stdout)fclose(out);free(buf);if(strcmp(statusopt,"none")&&strcmp(statusopt,"noxfer"))fprintf(stderr,"%llu+0 records in\n%llu+0 records out\n",(unsigned long long)records,(unsigned long long)records);return status;}
#endif
